#include "comms_hub.h"
#include <stdio.h>
#include <string.h>
#include <Hal.h>

#define VERSION_STRING "v1.0.0 2026-08-21"


// Populates pString with the given reset reason
void get_reset_reason_as_string(char * pString)
{
    enum Reset_Reason reset_reason = Hal_GetResetReason();

    switch (reset_reason) {
    case Reset_Reason_Powerup:
        sprintf(pString, "'Power-On Reset'");
        break;
    case Reset_Reason_Backup:
        sprintf(pString, "'Backup Reset'");
        break;
    case Reset_Reason_Watchdog:
        sprintf(pString, "'Watchdog Reset'");
        break;
    case Reset_Reason_Software:
        sprintf(pString, "'Software Reset'");
        break;
    case Reset_Reason_User:
        sprintf(pString, "'External Reset'");
        break;
    default:
        sprintf(pString, "UNKNOWN (%d)", reset_reason);
    }
}


// Private function: Sends a string over UART1
void transmit_bytes_over_uart1(char* pBytes)
{
    unsigned long charBuff;
    for (unsigned long i=0; i<strlen(pBytes); i++)
    {
        charBuff = pBytes[i];
        comms_hub_RI_uart1tx(&charBuff);
    }
}


// Private function: Sends a string over UART3
void transmit_bytes_over_uart3(char* pBytes)
{
    unsigned long charBuff;
    for (unsigned long i=0; i<strlen(pBytes); i++)
    {
        charBuff = pBytes[i];
        comms_hub_RI_uart3tx(&charBuff);
    }
}


// Constructor
void comms_hub_startup(void)
{
}


// CYCLIC IF handler: Invoked once per second
void comms_hub_PI_PeriodicStarter(void)
{
    char aMsgBuff[300];
    char aTmp[60];
    static int iUpSeconds = 0;

    // Periodic report: Version string
    sprintf(aMsgBuff, "TestTwinUarts %s\n", VERSION_STRING);

    // Periodic report: Uptime
    sprintf(aMsgBuff + strlen(aMsgBuff), "Uptime: %i seconds\n", ++iUpSeconds);

    // Periodic report: Reset reason
    get_reset_reason_as_string(aTmp);
    sprintf(aMsgBuff + strlen(aMsgBuff), "Reset reason: %s\n", aTmp);

    // Transmit over both channels
    transmit_bytes_over_uart1(aMsgBuff);
    transmit_bytes_over_uart3(aMsgBuff);

    // Also transmit the channel identities
    transmit_bytes_over_uart1("Channel: uart1\n\n");
    transmit_bytes_over_uart3("Channel: uart3\n\n");
}


// RECEVIER for uart1
void comms_hub_PI_uart1rx(const asn1SccT_UInt8 *p1)
{
    char aMsgBuff[100];
    sprintf(aMsgBuff, "-----------------------> Received over uart1: %lu\n\n", *p1);
    transmit_bytes_over_uart1(aMsgBuff);
}


// RECEVIER for uart3
void comms_hub_PI_uart3rx(const asn1SccT_UInt8 *p1)
{
    char aMsgBuff[100];
    sprintf(aMsgBuff, "-----------------------> Received over uart3: %lu\n\n", *p1);
    transmit_bytes_over_uart3(aMsgBuff);
}
